/* Grammar topics per language, in learning order. A topic's lesson is written by Claude the first time it's opened
   (src/lib/claude.ts writeLesson) from `covers`, and kept in the state (Lesson, id g_<topic id>).
   - Topic ids never change once shipped: lessons, drill progress and Talk corrections point at them.
   - `hints`: the words a gloss or a correction uses for this topic ("coffee (acc.)" → accusative), lower-case.
   Every language has a list (Spanish, French and Italian start at B1: I'm advanced there). */
import type { Lang } from "../types";

export type Level = "A1" | "A2" | "B1" | "B2";

export interface Topic {
  id: string;
  title: string;
  /** one line for the list */
  blurb: string;
  level: Level;
  /** what the lesson has to cover (for Claude) */
  covers: string;
  hints?: string[];
}

const PL: Topic[] = [
  { id: "pl-gender", level: "A1", title: "Gender of nouns", blurb: "Masculine, feminine, neuter: you can tell from the ending",
    covers: "How to tell a noun's gender from its ending (consonant = masculine, -a = feminine, -o/-e/-ę/-um = neuter) and the exceptions a beginner meets (mężczyzna, kolega masculine in -a; noc, rzecz feminine in a consonant). ten / ta / to and mój / moja / moje as gender markers." },
  { id: "pl-byc", level: "A1", title: "Być: to be, and personal pronouns", blurb: "jestem, jesteś, jest… and when to leave out ja, ty",
    covers: "The present of być in every person, the personal pronouns, dropping the pronoun because the ending shows the person, and to jest / to są. Mention that with a noun after it być takes the instrumental (jestem studentem) only briefly, as a preview.", hints: ["być"] },
  { id: "pl-present", level: "A1", title: "Present tense: the three patterns", blurb: "-am / -asz, -ę / -esz, -ę / -isz",
    covers: "Present tense conjugation of the three main patterns: -m/-sz (czytać: czytam, czytasz…), -ę/-esz (pisać: piszę, piszesz…, with consonant changes), -ę/-isz/-ysz (mówić, robić, uczyć się). Full tables for all persons, how to recognise the pattern from the infinitive, the common irregular ones (iść, jeść, mieć, chcieć, móc, wiedzieć).", hints: ["present", "pres."] },
  { id: "pl-acc", level: "A1", title: "Accusative (biernik)", blurb: "What you have, see, want, buy: kawa → kawę",
    covers: "The accusative singular and plural for each gender: feminine -a → -ę, masculine animate = genitive (-a: mam brata, psa), masculine inanimate and neuter unchanged, masculine personal plural = genitive plural. Adjectives in the accusative. Verbs that take it (mieć, lubić, widzieć, chcieć, kupić, jeść, pić, prosić o). Prepositions na and w with the accusative for direction (idę na plażę) and na + accusative of time.", hints: ["acc", "acc.", "accusative", "biernik"] },
  { id: "pl-neg-gen", level: "A1", title: "No + genitive: nie mam kawy", blurb: "After nie, the object goes into the genitive",
    covers: "The rule that a direct object (accusative) becomes genitive under negation: mam kawę → nie mam kawy, lubię psa → nie lubię psa, widzę ją → nie widzę jej; nie ma + genitive for 'there is no'. Genitive singular endings needed for it (-y/-i feminine, -a/-u masculine, -a neuter). Note that być, which takes the instrumental or nominative, doesn't change.", hints: ["neg.", "negation"] },
  { id: "pl-gen", level: "A2", title: "Genitive (dopełniacz)", blurb: "Of, quantities, and after bez, do, od, z, dla",
    covers: "Genitive singular and plural endings for each gender, including the -a / -u choice for masculine nouns (with the common patterns) and the plural endings (-ów, -i/-y, zero ending: kobiet, okien). Uses: possession (dom brata), quantities (dużo, mało, kilogram, butelka, pięć + gen. pl.), after prepositions (bez, do, od, z 'from', dla, u, obok, koło, podczas), after verbs (szukać, potrzebować, bać się, uczyć się). Adjectives in the genitive.", hints: ["gen", "gen.", "genitive", "dopełniacz"] },
  { id: "pl-loc", level: "A2", title: "Locative (miejscownik)", blurb: "Where you are and what about: w domu, na stole, o tobie",
    covers: "Locative endings: -e with consonant changes (stół → na stole, miasto → w mieście, Kraków → w Krakowie), -u (w domu, w parku after k/g/ch and soft consonants), feminine -e / -i / -y, plural -ach. Prepositions that always take it: w, na (location), o (about), przy, po (after; around). w vs na for places. Adjectives in the locative.", hints: ["loc", "loc.", "locative", "miejscownik"] },
  { id: "pl-ins", level: "A2", title: "Instrumental (narzędnik)", blurb: "With, by means of, and being: jestem lekarzem",
    covers: "Instrumental endings: -em (masculine and neuter), -ą (feminine), -ami plural (exceptions -mi: dziećmi, ludźmi). Uses: z + instrumental 'with' (kawa z mlekiem), the means (jadę autobusem, piszę długopisem), być / zostać + noun (jestem nauczycielem), interesować się, przed, za, nad, pod, między (location). Adjectives in the instrumental.", hints: ["ins", "ins.", "instr", "instr.", "instrumental", "narzędnik"] },
  { id: "pl-dat", level: "A2", title: "Dative (celownik)", blurb: "To whom: daję mamie, podoba mi się",
    covers: "Dative endings (-owi / -u masculine, -e / -i / -y feminine with consonant changes, -u neuter, -om plural). Uses: the person you give, show, tell something to (dać, pokazać, powiedzieć, pomagać, dziękować), feelings and states (zimno mi, podoba mi się, chce mi się), dzięki and ku. The dative pronouns mi / mnie, ci / tobie, mu / jemu, jej, nam, wam, im.", hints: ["dat", "dat.", "dative", "celownik"] },
  { id: "pl-adj", level: "A1", title: "Adjectives that agree", blurb: "dobry, dobra, dobre: gender, case and number",
    covers: "Adjective agreement in the nominative: -y/-i masculine, -a feminine, -e neuter, -i/-y masculine personal plural vs -e for everything else (dobrzy studenci, dobre kobiety). A full table of the hard adjective (dobry) across all seven cases, singular by gender and plural, and the soft one (tani) briefly. Word order (adjective before the noun, after it for a kind: kawa czarna).", hints: ["adj", "adj.", "adjective"] },
  { id: "pl-plural", level: "A2", title: "Plurals, and the men plural", blurb: "koty, kobiety, studenci: and why panowie is special",
    covers: "Nominative plural endings: -y / -i (koty, matki), -e (klucze, ulice), -a for neuter (okna), and the masculine personal plural with its consonant changes (student → studenci, Polak → Polacy, pan → panowie). How verbs and adjectives follow: oni / one in the present and past (byli / były). Common irregular plurals (ludzie, dzieci, ręce, oczy).", hints: ["pl.", "plural"] },
  { id: "pl-past", level: "A1", title: "Past tense, by gender", blurb: "byłem / byłam: the ending tells who and which gender",
    covers: "Forming the past tense from the infinitive stem + -ł- + gender ending + person ending: robiłem / robiłam, robiłeś / robiłaś, robił / robiła / robiło, robiliśmy / robiłyśmy, robili / robiły. Full tables for być, mieć, robić, and the irregular ones (iść: szedłem, szłam; jeść: jadłem; móc: mogłem; chcieć: chciałem). The masculine personal plural (-li) vs the rest (-ły), with ł → l changes (mieli, wzięli).", hints: ["past", "pst", "pst."] },
  { id: "pl-aspect", level: "A2", title: "Aspect: robić / zrobić", blurb: "In progress or done: the pairs behind past and future",
    covers: "Imperfective vs perfective verbs: ongoing or repeated (robić, pisać, czytać) vs one completed action (zrobić, napisać, przeczytać). How pairs are made (prefix: z-, na-, prze-; suffix change: kupować / kupić, dawać / dać; different verbs: brać / wziąć, mówić / powiedzieć). Which tenses each has: the perfective present form means future (zrobię). Signal words (codziennie, często, już, wczoraj cały dzień).", hints: ["pf", "pf.", "perf.", "perfective", "impf.", "imperfective", "aspect"] },
  { id: "pl-future", level: "A2", title: "Future: będę and the perfective", blurb: "będę czytać, będę czytał, przeczytam",
    covers: "The future of być (będę, będziesz…), the compound future of imperfective verbs (będę + infinitive or będę + past form: będę robić / będę robił, robiła), and the simple future of perfective verbs (zrobię, napiszę, kupię). When to use which (ongoing vs one completed thing).", hints: ["fut", "fut.", "future"] },
  { id: "pl-motion", level: "A2", title: "Going: iść / chodzić, jechać / jeździć", blurb: "On foot or by vehicle; now or regularly",
    covers: "The verbs of motion: iść (now, one direction) vs chodzić (habitually, there and back), jechać vs jeździć (by vehicle), lecieć / latać, nieść / nosić briefly. Present and past of each (idę, szedłem, szłam; jadę, jechałem). Prefixed forms for arriving and leaving (przyjść, wyjść, pojechać, wrócić). Where to: do + genitive (do sklepu), na + accusative (na pocztę), w with the accusative only in fixed phrases." },
  { id: "pl-pronouns", level: "A2", title: "Pronouns in every case", blurb: "mnie, mi, cię, ciebie, go, jego, mu, nią…",
    covers: "Personal pronouns in all seven cases, singular and plural, with the short (clitic) and long forms: mnie / mi, cię / ciebie / ci / tobie, go / jego / niego, mu / jemu / niemu, ją / jej / nią, and the n- forms after prepositions (do niego, z nią, o nich). When to use the long form (stress, start of a sentence, after a preposition). Possessives mój, twój, jego, jej, nasz, wasz, ich and swój." },
  { id: "pl-numbers", level: "B1", title: "Numbers and nouns", blurb: "dwa koty, pięć kotów: 2–4 vs 5 and up",
    covers: "How the noun after a number changes: 1 + nominative singular, 2–4 (and 22–24…) + nominative plural, 5+ (and 11–21, 25–31…) + genitive plural, with the verb in the singular neuter for 5+ (pięć kotów było). Masculine personal forms (dwaj / dwóch, trzech, pięciu panów) and collective numbers (dwoje dzieci) briefly. Telling the time and dates as a short example." },
  { id: "pl-modals", level: "A1", title: "Can, must, want: musieć, móc, chcieć", blurb: "+ infinitive; and trzeba, można, wolno",
    covers: "Present and past of musieć, móc, chcieć, umieć, wiedzieć vs znać, lubić + infinitive. Impersonal trzeba, można, wolno, warto + infinitive (trzeba iść). Negation (nie muszę, nie wolno)." },
  { id: "pl-cond", level: "B1", title: "Conditional: chciałbym", blurb: "would: politeness, wishes and if-sentences",
    covers: "Forming the conditional: past stem + by + person ending (chciałbym / chciałabym, zrobiłbyś, byłoby, mielibyśmy). Polite requests (Chciałbym kawę. Czy mógłby pan…?), wishes, and hypothetical if-sentences with gdyby (Gdybym miał czas, pojechałbym). The movable -by- (Gdzie byś poszedł?).", hints: ["cond", "cond.", "conditional"] },
  { id: "pl-imperative", level: "A2", title: "Imperative: zrób, chodź, proszę", blurb: "Telling and asking someone to do something",
    covers: "Forming the imperative from the 3rd person singular present (robi → rób, czyta → czytaj, pisze → pisz; perfective zrób, napisz), the plural and 'let's' forms (róbcie, zróbmy), negative imperatives with the imperfective (nie rób tego). Softening with proszę + infinitive and niech + 3rd person; common ones (chodź, daj, weź, powiedz, poczekaj).", hints: ["imp", "imp.", "imper.", "imperative"] },
  { id: "pl-voc", level: "B1", title: "Vocative (wołacz)", blurb: "Calling someone: Anno! Panie Tomku!",
    covers: "The vocative singular: feminine -a → -o (Anna → Anno, mama → mamo), -i/-u for soft and diminutive names (Kasiu, babciu), masculine -e with consonant changes (Piotr → Piotrze, pan → panie) or -u (Tomek → Tomku, syn → synu). Where it's used (addressing someone, in letters: Droga Mamo, Szanowny Panie) and that the plural equals the nominative.", hints: ["voc", "voc.", "vocative", "wołacz"] },
];

