export const GRAMMAR: Partial<Record<Lang, Topic[]>> = { ja: JA, pl: PL, ar: AR, el: EL, pt: PT, ru: RU, es: ES, fr: FR, it: IT, de: DE, nl: NL };

export const LEVEL_LABEL: Record<Level, string> = { A1: "A1 · First steps", A2: "A2 · Everyday", B1: "B1 · Independent", B2: "B2 · Fine points" };

export const hasGrammar = (lang: Lang) => (GRAMMAR[lang]?.length ?? 0) > 0;
export const topicsFor = (lang: Lang): Topic[] => GRAMMAR[lang] ?? [];
export const topicById = (lang: Lang, id: string | undefined): Topic | undefined => (id ? topicsFor(lang).find((t) => t.id === id) : undefined);
export const lessonId = (topic: string) => `g_${topic}`;

/** The topic a gloss's bracketed hint points at: "coffee (acc.)" → accusative. The longest hint that appears in the
    brackets as whole words wins, so "(subj. impf.)" is the imperfect subjunctive, not the imperfect. */
export function topicForHint(lang: Lang, text: string | undefined): Topic | undefined {
  if (!text) return;
  const inside = [...text.matchAll(/\(([^)]*)\)/g)].map((m) => ` ${m[1].toLowerCase().replace(/[,;/]/g, " ")} `);
  if (!inside.length) return;
  let best: { t: Topic; len: number } | undefined;
  for (const t of topicsFor(lang)) {
    for (const h of t.hints ?? []) {
      const forms = h.endsWith(".") ? [h, h.slice(0, -1)] : [h];
      if (forms.some((f) => inside.some((c) => c.includes(` ${f} `))) && (!best || h.length > best.len)) best = { t, len: h.length };
    }
  }
  return best?.t;
}
